 const themes={sage:{label:'내추럴 세이지',color:'#477560',surface:'#f2f5eb'},peach:{label:'따뜻한 살구',color:'#bb745a',surface:'#fcf1e8'},navy:{label:'차분한 네이비',color:'#4c647c',surface:'#eef2f5'},lavender:{label:'포근한 라벤더',color:'#8a7797',surface:'#f3eff6'},sand:{label:'크림 샌드',color:'#a48a56',surface:'#f7f2e7'},mono:{label:'화이트 미니멀',color:'#434b46',surface:'#f2f3f0'}};
 const shopDefaults=o=>({name:o.name,tagline:o.tag,theme:'sage',layout:'editorial',cardStyle:'soft',bannerHeight:300,announcement:'좋은 상품을 고르는 마음이, 우리 기관의 활동에 보탬이 됩니다.',announcementOn:true,bannerIds:[],sectionOrder:['featured','products','story'],sectionVisible:{featured:true,products:true,story:true},shippingFee:3000,freeShipping:50000,dispatchDays:'결제 확인 후 2~3영업일',carrier:'CJ대한통운',returnAddress:'기관 배송·반품 담당자 확인 후 안내 (예시)',returnFee:6000,phone:'문의 게시판 이용',hours:'평일 10:00–18:00',policy:'상품 수령 후 교환·반품을 문의해 주세요. 상품별 조건은 상세 안내를 확인해 주세요.',status:'운영 중'});
 const rootNames=['패션·잡화','리빙·주방','뷰티·케어','도서·취미'];
 function seedCategories(orgId){let sort=0;return rootNames.flatMap((name,i)=>{const id=orgId+'-c'+i;const childNames=[['의류','가방·잡화'],['주방용품','생활·인테리어'],['스킨케어','바디·케어'],['도서','취미·문구']][i];return [{id,org:orgId,name,parent:null,visible:true,sort:sort++},...childNames.map((n,j)=>({id:id+'-'+j,org:orgId,name:n,parent:id,visible:true,sort:j}))]})}
 function ensure(db){db.market??={};const m=db.market;m.shops??={};m.categories??={};m.claims??=[];m.coupons??=[];m.inquiries??=[];m.audit??=[];m.adjustments??=[];m.main??={notice:'좋은 상품을 고르고, 따뜻한 마음을 이어 주세요.',noticeOn:true,order:['live','featured','shops','new','story'],visible:{live:true,featured:true,shops:true,new:true,story:true},featured:[],featuredShops:[],categoryNames:rootNames.slice()};for(const o of db.orgs){m.shops[o.id]={...shopDefaults(o),...m.shops[o.id]};m.categories[o.id]??=seedCategories(o.id)}for(const p of db.products){p.sku??='BG-'+p.id.toUpperCase();p.saleStatus??='판매 중';p.recommended??=false;p.variants??=[];p.categoryId??=(m.categories[p.org]||[]).find(c=>c.name===p.category)?.id||m.categories[p.org]?.[0]?.id;p.createdAt??='2026-11-01T00:00:00.000Z';p.deliveryNote??='';p.brand??='';p.summary??=p.desc?.slice(0,80)||'';p.delivery??='기관 배송';const defaults={knit:'-c0-0',tote:'-c0-1',mug:'-c1-0',lamp:'-c1-1',serum:'-c2-0',book:'-c3-0'};if(!m.categoryMigration&&defaults[p.image]&&(m.categories[p.org]||[]).some(c=>c.id===p.categoryId&&!c.parent))p.categoryId=p.org+defaults[p.image];}m.categoryMigration=true;
 for(const o of db.orders){for(const item of o.items){const p=db.products.find(p=>p.id===item.id);item.org??=p?.org||db.orgs[0].id;item.name??=p?.name||'판매 상품';item.unitPrice??=p?.price||0;item.image??=p?.image||'hero';item.imageUploadId??=p?.imageUploadId;item.variantLabel??='기본';item.discount??=0;item.qty=Number(item.qty)}if(!o.fulfillments){const ids=[...new Set(o.items.map(i=>i.org))];o.fulfillments=ids.map((orgId,i)=>({org:orgId,status:o.status==='주문 취소'?'취소 완료':o.status||'상품 준비 중',carrier:'CJ대한통운',tracking:o.tracking||'',shipping:i===0?Math.max(0,o.total-o.items.reduce((n,i)=>n+i.unitPrice*i.qty,0)):0,stockRestored:false,note:''}))}o.createdAt??=(()=>{const parts=String(o.date).match(/\d+/g)||[];return parts.length>=3?`${parts[0]}-${parts[1].padStart(2,'0')}-${parts[2].padStart(2,'0')}T09:00:00.000Z`:new Date().toISOString()})();}
 if(!m.seeded){for(const o of db.orgs){const first=db.products.find(p=>p.org===o.id);if(first)first.recommended=true}m.coupons.push({id:'cp-demo-o1',org:'o1',name:'기관몰 첫 만남',code:'SMILE10',type:'percent',amount:10,min:20000,max:5000,limit:100,used:0,expires:'2027-12-31',active:true});m.inquiries.push({id:'Q-DEMO-01',org:'o1',name:'박방긋',title:'상품 소재와 배송 일정이 궁금해요',body:'티셔츠 소재와 출고 예정일을 알려 주세요.',status:'답변 대기',answer:'',date:'2026.11.05',mine:false});m.seeded=true}m.version=3;return m}
 function accountId(db){return db.session?.accountKey&&db.session.role===db.role?db.session.accountKey:db.role==='agency'?'agency:'+db.orgId:db.role==='buyer'&&db.buyerOrg?'buyer:'+db.buyerOrg:db.role||'buyer'}
 function rememberAccount(db){db.accountProfiles??={};const key=accountId(db);db.accountProfiles[key]??={};db.accountProfiles[key].details=structuredClone(db.profile||{});db.accountProfiles[key].shopping=Object.fromEntries(['cart','wishes','follows','alerts'].map(k=>[k,structuredClone(db[k]||[])]));return key}
 function activateAccount(db,role,orgId,session=null){assert([null,'buyer','individual','company','agency','admin'].includes(role),'계정 유형을 확인해 주세요.');if(orgId)assert(db.orgs.some(o=>o.id===orgId),'기관을 확인해 주세요.');rememberAccount(db);db.role=role;db.session=session;db.buyerOrg=session?.buyerOrg||null;if(orgId)db.orgId=orgId;const key=accountId(db);db.accountProfiles[key]??={};const names={buyer:'박방긋',individual:'김나눔',company:'주식회사 오늘',admin:'방긋 운영팀'};db.profile=structuredClone(db.accountProfiles[key].details||{name:role==='agency'?db.orgs.find(o=>o.id===db.orgId).name:names[role||'buyer'],email:'demo@example.com'});for(const list of ['cart','wishes','follows','alerts'])db[list]=structuredClone(db.accountProfiles[key].shopping?.[list]||[]);return key}
 function transferProduct(db,actor,id,targetOrg,donor){assert(actor?.role==='admin','기관 간 상품 이동은 최고관리자만 가능합니다.');const p=db.products.find(p=>p.id===id);assert(p,'상품을 확인해 주세요.');assert(db.orgs.some(o=>o.id===targetOrg),'기관을 확인해 주세요.');const current=ancestors(db,p.org,p.categoryId).at(-1),target=categories(db,targetOrg),category=target.find(c=>c.name===current?.name)||target.find(c=>c.name===p.category)||target[0];assert(category,'대상 기관에 카테고리를 먼저 만들어 주세요.');p.org=targetOrg;p.categoryId=category.id;p.category=category.name;if(donor)p.donor=donor;log(db,actor,'기관 매칭',p.name+' → '+targetOrg,targetOrg);return p}
 function permitted(actor,orgId){return actor?.role==='admin'||actor?.role==='agency'&&actor.org===orgId}
 function guard(actor,orgId){assert(permitted(actor,orgId),'이 기관의 내역을 관리할 권한이 없습니다.')}
 function log(db,actor,type,text,orgId){db.market.audit.unshift({id:uid('L'),at:new Date().toISOString(),role:actor?.role||'buyer',org:orgId||null,type,text});db.market.audit=db.market.audit.slice(0,150)}
 function categories(db,orgId){return (db.market.categories[orgId]||[]).slice().sort((a,b)=>a.sort-b.sort)}
 function ancestors(db,orgId,id){const list=categories(db,orgId),out=[],seen=new Set();let current=list.find(c=>c.id===id);while(current){assert(!seen.has(current.id),'카테고리를 순환 연결할 수 없습니다.');seen.add(current.id);out.unshift(current);current=list.find(c=>c.id===current.parent)}return out}
 function descendants(db,orgId,id){const list=categories(db,orgId),found=new Set([id]);let changed=true;while(changed){changed=false;for(const c of list)if(c.parent&&found.has(c.parent)&&!found.has(c.id)){found.add(c.id);changed=true}}return found}
 function categoryVisible(db,p){const list=ancestors(db,p.org,p.categoryId);return list.length>0&&list.every(c=>c.visible)}
 function publicProduct(db,p){return p&&p.saleStatus!=='판매 중지'&&p.saleStatus!=='임시 저장'&&db.market.shops[p.org]?.status==='운영 중'&&categoryVisible(db,p)}
 function saveCategory(db,actor,data){guard(actor,data.org);const list=db.market.categories[data.org];assert(list,'기관을 확인해 주세요.');const old=list.find(c=>c.id===data.id);const name=String(data.name||'').trim();assert(name&&name.length<=30,'카테고리 이름을 30자 이내로 입력해 주세요.');const parent=data.parent||null;assert(!parent||list.some(c=>c.id===parent),'상위 카테고리를 확인해 주세요.');if(old)assert(!descendants(db,data.org,old.id).has(parent),'자기 자신이나 하위 카테고리를 상위로 지정할 수 없습니다.');const parentDepth=parent?ancestors(db,data.org,parent).length:0;const subtreeDepth=old?Math.max(...[...descendants(db,data.org,old.id)].map(id=>ancestors(db,data.org,id).length-ancestors(db,data.org,old.id).length)):0;assert(parentDepth+1+subtreeDepth<=3,'카테고리는 3단계까지 구성할 수 있습니다.');assert(!list.some(c=>c.id!==old?.id&&c.parent===parent&&c.name===name),'같은 위치에 같은 이름의 카테고리가 있습니다.');const item={id:old?.id||uid('cat'),org:data.org,name,parent,visible:!!data.visible,sort:old?.sort??list.filter(c=>c.parent===parent).length};if(old)Object.assign(old,item);else list.push(item);log(db,actor,'카테고리',name+' '+(old?'수정':'추가'),data.org);return item}
 function deleteCategory(db,actor,orgId,id){guard(actor,orgId);const list=db.market.categories[orgId];assert(!list.some(c=>c.parent===id),'하위 카테고리를 먼저 이동하거나 삭제해 주세요.');assert(!db.products.some(p=>p.org===orgId&&p.categoryId===id),'이 카테고리의 상품을 다른 카테고리로 이동해 주세요.');db.market.categories[orgId]=list.filter(c=>c.id!==id);log(db,actor,'카테고리','빈 카테고리 삭제',orgId)}
 function reorderCategory(db,actor,orgId,id,direction){guard(actor,orgId);const list=categories(db,orgId),item=list.find(c=>c.id===id);assert(item,'카테고리를 확인해 주세요.');const siblings=list.filter(c=>c.parent===item.parent),i=siblings.findIndex(c=>c.id===id),j=i+direction;if(j<0||j>=siblings.length)return;const original=db.market.categories[orgId];[siblings[i],siblings[j]]=[siblings[j],siblings[i]];siblings.forEach((x,n)=>{original.find(c=>c.id===x.id).sort=n})}
 function productStock(p,variantId){if(p.variants?.length){const v=p.variants.find(v=>v.id===variantId);assert(v&&!v.retired,'상품 옵션을 선택해 주세요.');return v.stock}return p.stock}
 function productPrice(p,variantId){if(!p.variants?.length)return p.price;const v=p.variants.find(v=>v.id===variantId);assert(v,'상품 옵션을 선택해 주세요.');return p.price+v.extra}
 function saveProduct(db,actor,data){guard(actor,data.org);const old=db.products.find(p=>p.id===data.id);if(old)guard(actor,old.org);const name=String(data.name||'').trim();assert(name&&name.length<=100,'상품명을 100자 이내로 입력해 주세요.');const price=num(data.price,1),original=num(data.original||price,1);assert(original>=price,'정상가는 판매가 이상으로 입력해 주세요.');assert(categories(db,data.org).some(c=>c.id===data.categoryId),'상품 카테고리를 선택해 주세요.');assert(['판매 중','판매 중지','임시 저장'].includes(data.saleStatus),'판매 상태를 확인해 주세요.');const variants=(data.variants||[]).map(v=>({id:v.id||uid('v'),label:String(v.label||'').trim(),extra:num(v.extra||0),stock:num(v.stock,0,100000)}));assert(variants.every(v=>v.label&&v.label.length<=60),'옵션 이름을 입력해 주세요.');assert(new Set(variants.map(v=>v.label)).size===variants.length,'같은 옵션 이름을 중복 등록할 수 없습니다.');const p={...old,...data,id:old?.id||uid('p'),name,price,original,stock:variants.length?variants.reduce((n,v)=>n+v.stock,0):num(data.stock,0,100000),variants,createdAt:old?.createdAt||new Date().toISOString()};p.sku=String(data.sku||old?.sku||'BG-'+p.id.toUpperCase()).trim();p.category=categories(db,data.org).find(c=>c.id===data.categoryId).name;if(old)Object.assign(old,p);else db.products.unshift(p);log(db,actor,'상품',name+' '+(old?'수정':'등록'),data.org);return p}
 function bulkProducts(db,actor,ids,patch){const products=ids.map(id=>db.products.find(p=>p.id===id));assert(products.length&&products.every(Boolean),'상품을 선택해 주세요.');for(const p of products){guard(actor,p.org);if(patch.categoryId)assert(categories(db,p.org).some(c=>c.id===patch.categoryId),'같은 기관의 카테고리로만 이동할 수 있습니다.')}for(const p of products)Object.assign(p,patch);log(db,actor,'상품',products.length+'개 상품 일괄 변경',actor.org)}
 function itemTotal(items){return items.reduce((n,i)=>n+i.unitPrice*i.qty-(i.discount||0),0)}
 function orderRows(db,actor,filter='all'){const rows=[];for(const order of db.orders)for(const f of order.fulfillments||[]){if(actor?.role==='agency'&&f.org!==actor.org)continue;if(filter!=='all'&&f.org!==filter)continue;const items=order.items.filter(i=>i.org===f.org);rows.push({key:key(order.id,f.org),orderId:order.id,org:f.org,items,fulfillment:f,name:order.name,date:order.date,createdAt:order.createdAt,address:order.address,total:itemTotal(items)+f.shipping,merchandise:itemTotal(items),order})}return rows}
 function couponDiscount(db,coupon,cart){if(!coupon)return 0;assert(coupon.active,'사용할 수 없는 쿠폰입니다.');assert(coupon.expires>=new Date().toISOString().slice(0,10),'사용 기간이 지난 쿠폰입니다.');assert(coupon.used<coupon.limit,'쿠폰 사용 가능 수량이 소진되었습니다.');const eligible=cart.filter(c=>!coupon.org||db.products.find(p=>p.id===c.id)?.org===coupon.org);const amount=eligible.reduce((n,c)=>{const p=db.products.find(p=>p.id===c.id);return n+productPrice(p,c.variantId)*c.qty},0);assert(amount>=coupon.min,'쿠폰 최소 주문 금액을 확인해 주세요.');const discount=coupon.type==='percent'?Math.floor(amount*coupon.amount/100):coupon.amount;return Math.min(amount,discount,coupon.max||Infinity)}
 function quote(db,cart,couponId){assert(cart.length,'장바구니가 비어 있습니다.');const coupon=db.market.coupons.find(c=>c.id===couponId),discount=couponDiscount(db,coupon,cart);const requested=new Map();for(const c of cart){const p=db.products.find(p=>p.id===c.id);assert(p,'상품을 확인해 주세요.');const k=c.id+':'+(c.variantId||'');requested.set(k,(requested.get(k)||0)+num(c.qty,1,100000));assert(productStock(p,c.variantId)>=requested.get(k),'선택한 상품의 합산 수량이 재고를 초과했습니다.')}const items=cart.map(c=>{const p=db.products.find(p=>p.id===c.id);assert(publicProduct(db,p),'판매하지 않는 상품이 장바구니에 있습니다.');const amount=num(c.qty,1,100000);assert(productStock(p,c.variantId)>=amount,'상품 재고가 변경되었습니다: '+p.name);return {id:p.id,org:p.org,qty:amount,unitPrice:productPrice(p,c.variantId),name:p.name,image:p.image,imageUploadId:p.imageUploadId,variantId:c.variantId||null,variantLabel:p.variants.find(v=>v.id===c.variantId)?.label||'기본',discount:0}});let remaining=discount;const eligible=items.filter(i=>!coupon?.org||i.org===coupon.org),eligibleTotal=eligible.reduce((n,i)=>n+i.unitPrice*i.qty,0);eligible.forEach((i,index)=>{i.discount=index===eligible.length-1?remaining:Math.floor(discount*i.unitPrice*i.qty/eligibleTotal);remaining-=i.discount});const groups=[...new Set(items.map(i=>i.org))].map(orgId=>{const subset=items.filter(i=>i.org===orgId),subtotal=itemTotal(subset),settings=db.market.shops[orgId];return {org:orgId,items:subset,subtotal,shipping:settings.freeShipping>0&&subtotal>=settings.freeShipping?0:settings.shippingFee}});return {items,groups,subtotal:items.reduce((n,i)=>n+i.unitPrice*i.qty,0),discount,shipping:groups.reduce((n,g)=>n+g.shipping,0),total:groups.reduce((n,g)=>n+g.subtotal+g.shipping,0),coupon}}
 function changeStock(db,item,delta){const p=db.products.find(p=>p.id===item.id);if(!p)return;if(item.variantId){const v=p.variants.find(v=>v.id===item.variantId);if(v){v.stock+=delta}else if(delta>0){p.variants.push({id:item.variantId,label:item.variantLabel,extra:Math.max(0,item.unitPrice-p.price),stock:delta,retired:true})}p.stock=p.variants.filter(v=>!v.retired).reduce((n,v)=>n+v.stock,0)}else p.stock+=delta}
 function checkout(db,cart,details,couponId){const q=quote(db,cart,couponId);assert(String(details.name||'').trim()&&String(details.address||'').trim(),'수령인과 배송지를 확인해 주세요.');const order={id:uid('B'),name:details.name,address:details.address,phone:details.phone||'',memo:details.memo||'',items:q.items,total:q.total,couponId:q.coupon?.id||null,date:new Date().toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}),createdAt:new Date().toISOString(),mine:true,payment:details.payment||'카드 체험',fulfillments:q.groups.map(g=>({org:g.org,status:'신규 주문',carrier:db.market.shops[g.org].carrier,tracking:'',shipping:g.shipping,stockRestored:false,note:''}))};for(const i of q.items)changeStock(db,i,-i.qty);if(q.coupon)q.coupon.used++;db.orders.unshift(order);log(db,{role:'buyer'},'주문',order.id+' 주문 체험 생성',null);return order}
 function fulfillment(db,actor,orderId,orgId){guard(actor,orgId);const order=db.orders.find(o=>o.id===orderId),f=order?.fulfillments.find(f=>f.org===orgId);assert(order&&f,'주문을 찾을 수 없습니다.');return {order,f,items:order.items.filter(i=>i.org===orgId)}}
