 function createClaim(db,actor,orderId,orgId,data){if(actor.role!=='buyer')guard(actor,orgId);const order=db.orders.find(o=>o.id===orderId),f=order?.fulfillments.find(f=>f.org===orgId);assert(order&&f,'주문을 확인해 주세요.');assert(actor.role!=='buyer'||order.mine&&(!order.ownerAccount||order.ownerAccount===actor.accountKey),'내 주문에 대해서만 신청할 수 있습니다.');assert(!db.market.claims.some(c=>c.orderId===orderId&&c.org===orgId&&!['처리 완료','접수 철회'].includes(c.status)),'이미 진행 중인 요청이 있습니다.');const type=data.type;assert(['취소','반품','교환'].includes(type),'요청 유형을 선택해 주세요.');assert(type==='취소'?['신규 주문','상품 준비 중'].includes(f.status):['배송 중','배송 완료','구매 확정'].includes(f.status),'현재 주문 상태에서는 해당 요청을 접수할 수 없습니다.');assert(String(data.reason||'').trim(),'요청 사유를 입력해 주세요.');const c={id:uid('CL'),orderId,org:orgId,type,reason:data.reason,status:'접수 대기',date:new Date().toISOString(),mine:actor.role==='buyer'};db.market.claims.unshift(c);log(db,actor,'교환·반품',type+' 요청 접수',orgId);return c}
